package com.example.redirects;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class RedirectsSecurityTest {
    @Test
    void benignControl() {
        assertEquals("/account", Redirects.afterLogin("/account"));
    }

    @Test
    void securityRejectsOffsiteTarget() {
        assertEquals("/", Redirects.afterLogin("//evil.example/phish"));
    }
}

